 para('**Når en automatisering stopper, skal der ikke bruges tid på at finde ud af, hvem der ejer den.** For Nykredit handler Run Operations Lead om at samle de opgaver, der i dag ligger hos flere personer, og skabe en driftsmodel, som fungerer for både forretningen og driftsteamet i Polen. Det er en forudsætning for at omsætte automatisering til hurtig, synlig værdi og samtidig beskytte kvaliteten i kundeoplevelsen.')
 para('Første skridt er et fælles overblik over løsninger, ejere, afhængigheder og åbne driftsopgaver. Derefter kan Process Automation og kollegerne i Polen aftale en enkel driftsrytme: hvad overvåges, hvem reagerer, hvornår eskaleres en fejl, og hvordan følges den til dørs? En fælles prioritering af drifts- og projektopgaver gør det muligt at løse dagens hændelser uden at miste forbedringerne af syne.')
 para('**PLC-processen og Power Platform:** PLC-processens eksisterende betydning, faser og beslutningsrettigheder afklares med Nykredit, før den ændres. En aftalt proces kan derefter samle krav, test, godkendelse, overdragelse, ændringer og afvikling med tydelig dokumentation. For Power Platform foreslås et miljø- og ejerregister, en proces for adgangstildeling og -fjernelse, relevante kontroller og monitorering samt en ansvarlig for opfølgning. Kontroller og rettigheder fastlægges sammen med platform-, sikkerheds- og forretningsansvarlige.')
 para('**Citizen Development:** En løsning bør have en kendt ejer, en enkel dokumentation af formål, datakilder og afhængigheder samt en aftale om support og overdragelse, før den bliver kritisk for forretningen. Et proportionalt review efter risiko kan give kolleger frihed til at forbedre arbejdsgange uden at efterlade driftsteamet med løsninger, ingen kan overtage.')
 para('Det relevante grundlag er drift, koordinering og automatisering fra flere miljøer: hos Data Power omfattede arbejdet tekniske applikationer fra behov og integration til dokumentation og overdragelse; egne AI-kodede løsninger hos ELOHVAC understøtter planlægning og kvalitet med en dokumenteret produktivitetsforbedring på over 40 %. Erfaringen omfatter praktisk Power Platform-administration og fuldt ansvar for PLC, mens Nykredits konkrete konfiguration, proces og ansvar skal afklares. Min automatiseringserfaring omfatter egen AI-kodet platform; specifik UiPath-erfaring og forvaltning af citizen development er ikke dokumenteret.')
 para('Nykredit beskriver en foreningsejet virksomhed med fokus på kunder og lokalsamfund. Sammen med teamets faglige kvalitet, sammenhold og humor peger det på en drift, der gør det nemmere for kolleger at levere — og som kan forklares, deles og forbedres. Jeg vil gerne drøfte, hvor de nuværende overdragelser skaber mest friktion, og hvilken forbedring teamet bør starte med.')
 m.meta('Med venlig hilsen',after=5);m.meta('Shahram Ajloo · +45 93 99 95 14 · ajlooshahram@gmail.com',after=0)
 m.page_break();m.resume_header(NAME,TITLE,CONTACT,'OPGAVEN — SAMMENHÆNGENDE DRIFT FRA FORRETNING TIL POLEN')
 m.para('Nykredits CoE har brug for klare ejere, kontroller og overdragelser på tværs af automatiseringsløsninger. Grundlaget er erfaring med teknisk drift, digital automatisering, kundebehov og dokumenteret overdragelse: ELOHVACs egne AI-værktøjer med over 40 % produktivitetsløft; Data Powers tekniske applikationer fra behov til driftsoverdragelse; Novo Nordisks 37 projekter og 25 specialister i et reguleret miljø. Praktisk Power Platform-administration og fuldt PLC-ansvar er oplyst af kandidaten; omfang og sammenhæng med Nykredits PLC-proces afklares.',after=30)
 m.section('OVERBLIK, AFTALE, KONTROL — TILGANG TIL ROLLEN')
 for a,b in [('Overblik','Kortlæg løsninger, afhængigheder, ejere, miljøer, hændelser og igangværende projekter med forretning, drift og platformansvarlige.'),('Aftale','Fordel ansvar for drift, ændringer og support; aftal eskalering, overdragelse og fælles prioritering med teamet i Polen.'),('Kontrol','Følg op på adgange, monitorering, tilbagevendende fejl og dokumentation; vælg forbedringer ud fra konsekvens for kunder og kolleger.')]:m.bullet(a,b,after=10)
 m.section('ERFARING')
 jobs=[('Ejer / teknisk direktør','ELOHVAC ApS · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Automatisering og effekt','Udviklede AI-baserede værktøjer til tilbud, tidsplaner, kvalitetstjek og KPI-overblik; dokumenteret produktivitetsløft på over 40 %.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · 2024–nov. 2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden er ophørt',[('Behov til overdragelse','Ledede tekniske og industrielle applikationer fra krav og integration til idriftsættelse, dokumentation og overdragelse til kundens drift.'),('Udviklingsdisciplin','Indførte AI-assisteret softwareudvikling med kode-review og test; styrede prioriteringer på tværs af to samtidige organisationer.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Koordinering og dokumentation','Sammenholdt fremdrift, økonomi og risici på tværs af engineering, indkøb og anlæg. FAT/SAT og IQ/OQ/PQ i GMP-miljø; nul kritiske afvigelser ved aflevering.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Fælles prioritering','Ledede daglig kapacitets- og fremdriftsstyring med tavlemøder og flaskehalsanalyse på tværs af projekter.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk teknisk drift · 24/7',[('Drift og opfølgning','Forebyggende vedligehold og fejlfinding i el- og mekaniske anlæg, SCADA, skifteholdsdrift og sikkerhedsrutiner.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere',[('Planlægning','Ledede skifteplanlægning og materialekoordinering samt fejlretning på industrielle anlæg.')])]
 for t,meta,scope,bullets in jobs:
  m.job(t,meta,scope=scope)
  for a,b in bullets:m.bullet(a,b,after=10)
 m.page_break();m.section('UDDANNELSE OG VÆRKTØJER')
 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Værktøjer:** Power Platform-administration (praktisk erfaring oplyst af kandidaten; konkrete områder skal afklares), Python, Claude API, Excel og SAP ERP. **Metoder:** PRINCE2, Lean og Six Sigma anvendt i praksis; alene PRINCE2 er certificeret. **Sprog:** dansk, engelsk og persisk.',after=20)
 rows=[('Samle drift og projektopgaver','ELOHVAC: fuldt P&L og koordinering af teknikere og leverancer; Ventek-Air: 14 personer og 11 projekter. Vil samle ejere, opgaver, prioritet og eskalering i én fælles driftsrytme.'),('Samarbejde med driftsteamet i Polen','Data Power: dokumenterede applikationer og overdragelse til kundedrift. Vil aftale skriftlige runbooks, kontaktveje, feedback og tydelig arbejdsdeling med teamet i Polen.'),('PLC-processen for automatiseringsløsninger','Kandidaten oplyser at have haft fuldt ansvar for PLC. Betydning, kontekst og omfang er ikke specificeret; Nykredits proces afklares, før der foreslås ændringer.'),('Power Platform: miljøer og adgange','Kandidaten bekræfter praktisk administration af Power Platform; hvilke miljøer og adgangsopgaver er ikke specificeret. Vil kortlægge miljøer, ejere og adgangsproces sammen med platformansvarlige.'),('Kontroller, monitorering og løsningsejerskab','Egne AI-værktøjer og KPI-overblik i ELOHVAC; foreslår aftalte kontroller, ejere og overvågning efter Nykredits sikkerhedskrav. Konkrete Power Platform-kontroller er ikke specificeret.'),('Citizen Development: dokumentation, overdragelse og support','Data Power leverede dokumentation og overdragelse af tekniske applikationer. Specifikt ansvar for citizen development er ikke dokumenteret; foreslår risikobaseret review og supportaftale.'),('Governance, standarder og ansvarsfordeling','Novo: 37 projekter med koordination og dokumentation i GMP. Vil etablere ejere, beslutningsveje, processer og standarder sammen med drift, sikkerhed og forretning.'),('Automatiseringsteknologier og UiPath','Egen AI-kodet platform og Python/Claude-baserede værktøjer er oplyst; specifik UiPath-erfaring er ikke dokumenteret. Lær Nykredits teknologier og eksisterende arbejdsgange.'),('Forretning og teknik, interessenter og kommunikation','Data Power omsatte kundebehov til tekniske applikationer; Novo koordinerede 25 specialister på tværs af engineering, indkøb og anlæg med løbende rapportering.'),('Stabil drift, opfølgning og forbedring','BIOFOS: kritisk 24/7-drift og forebyggende vedligehold; ELOHVAC: over 40 % produktivitetsløft via AI-værktøjer. Vil prioritere gentagne fejl og forbedringer med relevante ejere.'),('Faglig kvalitet, sammenhold og udvikling','FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering; 1:1 og oplæring af elektrikere og lærlinge. Del viden og udvikl standarderne med kollegerne.')]
 m.models_table('OPGAVEN — EVIDENS OG FORESLÅET HANDLING',('Krav i rollen','Erfaring eller første tilgang'),rows,widths=(2550,7796))
